import{_ as a,o as n,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"访问控制与限流","description":"allow/deny 的顺序语义、auth_basic 与 auth_request、漏桶限流的 burst/nodelay 与连接数限制。","frontmatter":{"title":"访问控制与限流","description":"allow/deny 的顺序语义、auth_basic 与 auth_request、漏桶限流的 burst/nodelay 与连接数限制。","source":"https://daiw.org/manual/nginx/access-limits"},"headers":[],"relativePath":"manual/tools/nginx/access-limits.md","filePath":"manual/tools/nginx/access-limits.md"}'),l={name:"manual/tools/nginx/access-limits.md"};function t(i,s,r,c,o,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="访问控制与限流" tabindex="-1">访问控制与限流 <a class="header-anchor" href="#访问控制与限流" aria-label="Permalink to &quot;访问控制与限流&quot;">​</a></h1><h2 id="allow-deny" tabindex="-1">allow / deny <a class="header-anchor" href="#allow-deny" aria-label="Permalink to &quot;allow / deny&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    allow address | CIDR | unix: | all;</span></span>
<span class="line"><span>         deny  address | CIDR | unix: | all;</span></span>
<span class="line"><span>上下文:  http, server, location, limit_except</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /admin/ {</span></span>
<span class="line"><span>    allow 192.168.1.0/24;</span></span>
<span class="line"><span>    allow 10.0.0.1;</span></span>
<span class="line"><span>    deny  all;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>按书写顺序自上而下匹配，第一条命中即生效。</strong> 所以 <code>deny all;</code> 必须写在最后——写在前面会把后面的 <code>allow</code> 全废掉。</p><p>拒绝时返回 <strong><code>403</code></strong>。</p><p><strong><code>allow</code>/<code>deny</code> 判断的是 <code>$remote_addr</code>——即直连 nginx 的对端地址。</strong></p><p>nginx 前面有 CDN 或负载均衡时，<code>$remote_addr</code> 是<strong>那台代理的 IP</strong>，不是真实用户 IP。此时基于 IP 的访问控制会<strong>全部失效</strong>（要么全放行要么全拒绝）。</p><p>解法是 <code>ngx_http_realip_module</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set_real_ip_from 10.0.0.0/8;        # 信任的代理网段</span></span>
<span class="line"><span>real_ip_header   X-Forwarded-For;</span></span>
<span class="line"><span>real_ip_recursive on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>它会按信任列表从 <code>X-Forwarded-For</code> 中还原真实 IP 并<strong>改写 <code>$remote_addr</code></strong>。</p><p><code>set_real_ip_from</code> <strong>必须精确列出可信代理</strong>——写成 <code>0.0.0.0/0</code> 等于让任何人都能伪造自己的 IP。这与 <a href="https://daiw.org/manual/http11/proxy-fields" target="_blank" rel="noreferrer">HTTP 转发字段的安全模型</a>是同一条原则。</p><h2 id="limit-except" tabindex="-1">limit_except <a class="header-anchor" href="#limit-except" aria-label="Permalink to &quot;limit\\_except&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /upload/ {</span></span>
<span class="line"><span>    limit_except GET HEAD {</span></span>
<span class="line"><span>        allow 192.168.1.0/24;</span></span>
<span class="line"><span>        deny  all;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>语义是反的</strong>：限制<strong>除了</strong>列出方法之外的所有方法。上面表示 GET/HEAD 任何人可用，其他方法（POST/PUT/DELETE）只允许内网。</p><p>注意 <code>GET</code> 会<strong>自动包含 <code>HEAD</code></strong>（<a href="https://daiw.org/manual/http11/methods" target="_blank" rel="noreferrer">HTTP 语义上 HEAD 是 GET 的无体版本</a>）。</p><h2 id="auth-basic" tabindex="-1">auth_basic <a class="header-anchor" href="#auth-basic" aria-label="Permalink to &quot;auth\\_basic&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    auth_basic string | off;      默认: off</span></span>
<span class="line"><span>         auth_basic_user_file file;</span></span>
<span class="line"><span>上下文:  http, server, location, limit_except</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /private/ {</span></span>
<span class="line"><span>    auth_basic           &quot;Restricted Area&quot;;</span></span>
<span class="line"><span>    auth_basic_user_file /etc/nginx/.htpasswd;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>那个字符串是 <a href="https://daiw.org/manual/http11/authentication" target="_blank" rel="noreferrer"><code>WWW-Authenticate</code> 挑战里的 <code>realm</code></a>，会显示在浏览器弹窗里。</p><p>密码文件用 <code>htpasswd</code> 生成（支持 <code>bcrypt</code>、<code>apr1</code>、crypt）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>htpasswd -B -c /etc/nginx/.htpasswd alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://daiw.org/manual/http11/authentication" target="_blank" rel="noreferrer">Basic 认证的 Base64 不是加密</a>——<strong>必须在 TLS 上使用</strong>，否则等于明文传密码。</p><p>嵌套 location 里要关掉继承的认证，用 <code>auth_basic off;</code>。</p><h2 id="auth-request" tabindex="-1">auth_request <a class="header-anchor" href="#auth-request" aria-label="Permalink to &quot;auth\\_request&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /private/ {</span></span>
<span class="line"><span>    auth_request /auth;</span></span>
<span class="line"><span>    proxy_pass   http://backend;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location = /auth {</span></span>
<span class="line"><span>    internal;</span></span>
<span class="line"><span>    proxy_pass              http://auth-service/verify;</span></span>
<span class="line"><span>    proxy_pass_request_body off;              # 不转发请求体</span></span>
<span class="line"><span>    proxy_set_header        Content-Length &quot;&quot;;</span></span>
<span class="line"><span>    proxy_set_header        X-Original-URI $request_uri;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>（需 <code>--with-http_auth_request_module</code>）</p><p>把鉴权<strong>委托给一个子请求</strong>：</p><table tabindex="0"><thead><tr><th>子请求返回</th><th>nginx 行为</th></tr></thead><tbody><tr><td><code>2xx</code></td><td>放行</td></tr><tr><td><code>401</code> / <code>403</code></td><td>拒绝，原样返回该状态</td></tr><tr><td>其他</td><td><code>500</code></td></tr></tbody></table><p>要点：</p><ul><li><strong><code>internal;</code></strong> 让 <code>/auth</code> 只能被内部子请求访问，外部直接请求返回 404。</li><li><strong><code>proxy_pass_request_body off</code></strong> 避免把请求体（可能很大）也发给鉴权服务。</li><li>用 <code>auth_request_set</code> 把鉴权服务返回的信息传给上游：</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auth_request_set $user $upstream_http_x_user;</span></span>
<span class="line"><span>proxy_set_header X-User $user;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这是把 SSO/OAuth 网关接进 nginx 的标准模式。</p><h2 id="limit-req-漏桶限流" tabindex="-1">limit_req：漏桶限流 <a class="header-anchor" href="#limit-req-漏桶限流" aria-label="Permalink to &quot;limit\\_req：漏桶限流&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    limit_req_zone key zone=name:size rate=rate [sync];</span></span>
<span class="line"><span>上下文:  http</span></span>
<span class="line"><span></span></span>
<span class="line"><span>语法:    limit_req zone=name [burst=number] [nodelay | delay=number];</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    limit_req_zone $binary_remote_addr zone=one:10m rate=10r/s;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    server {</span></span>
<span class="line"><span>        location /api/ {</span></span>
<span class="line"><span>            limit_req zone=one burst=20 nodelay;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>官方明确说明用的是 <strong>漏桶（leaky bucket）</strong> 算法。</p><h3 id="key-用-binary-remote-addr" tabindex="-1">key 用 $binary_remote_addr <a class="header-anchor" href="#key-用-binary-remote-addr" aria-label="Permalink to &quot;key 用 $binary\\_remote\\_addr&quot;">​</a></h3><p><strong>不要用 <code>$remote_addr</code></strong>——它是点分十进制字符串（IPv4 最多 15 字节），而 <code>$binary_remote_addr</code> 是<strong>二进制形式</strong>（IPv4 仅 4 字节）。同样的 zone 大小能存更多状态。</p><p>zone 容量（官方给的数字）：</p><table tabindex="0"><thead><tr><th>平台</th><th>每状态</th><th>每 MB 状态数</th></tr></thead><tbody><tr><td>32 位</td><td>64 字节</td><td>约 <strong>16000</strong></td></tr><tr><td>64 位</td><td>128 字节</td><td>约 <strong>8000</strong></td></tr></tbody></table><p>所以 <code>zone=one:10m</code> 在 64 位上约存 8 万个 IP。<strong>zone 满了新请求会被拒绝</strong>（返回 <code>503</code>），且会记 error 日志。</p><h3 id="rate" tabindex="-1">rate <a class="header-anchor" href="#rate" aria-label="Permalink to &quot;rate&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rate=10r/s;    # 每秒 10 个</span></span>
<span class="line"><span>rate=30r/m;    # 每分钟 30 个 = 0.5r/s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>r/m</code> 用于低频限制——<code>rate=1r/m</code> 比 <code>rate=0.016r/s</code> 好写得多（后者也不合法）。</p><p>nginx 内部按<strong>毫秒</strong>粒度平滑：<code>10r/s</code> 实际是「每 100ms 允许 1 个」，而不是「每秒开头放 10 个」。</p><h3 id="burst-与-nodelay" tabindex="-1">burst 与 nodelay <a class="header-anchor" href="#burst-与-nodelay" aria-label="Permalink to &quot;burst 与 nodelay&quot;">​</a></h3><p>这是最需要理解的一对：</p><table tabindex="0"><thead><tr><th>配置</th><th>行为</th></tr></thead><tbody><tr><td><code>limit_req zone=one;</code></td><td>严格 10r/s，<strong>超出立即 503</strong></td></tr><tr><td><code>limit_req zone=one burst=20;</code></td><td>超出的排队<strong>延迟处理</strong>，队列满 20 才 503</td></tr><tr><td><code>limit_req zone=one burst=20 nodelay;</code></td><td>超出的<strong>立即处理</strong>不排队，但仍占用桶容量</td></tr><tr><td><code>limit_req zone=one burst=20 delay=10;</code></td><td>前 10 个立即处理，第 11–20 个延迟，超过 20 拒绝</td></tr></tbody></table><p><strong>没有 <code>burst</code> 时限流极其严酷</strong>：页面加载会同时发几十个请求，10r/s 会把绝大部分打成 503。真实场景基本都要配 <code>burst</code>。</p><p><strong><code>nodelay</code> 通常是想要的</strong>：允许突发但维持长期平均速率。不加 <code>nodelay</code> 时请求会被<strong>人为延迟</strong>，用户感觉是「网站变慢」而不是「被限流」。</p><h3 id="状态码与日志" tabindex="-1">状态码与日志 <a class="header-anchor" href="#状态码与日志" aria-label="Permalink to &quot;状态码与日志&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>limit_req_status    503;      默认</span></span>
<span class="line"><span>limit_req_log_level error;    默认（延迟的记低一级 = warn）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>建议改成 429</strong>——<a href="https://daiw.org/manual/http11/status-4xx" target="_blank" rel="noreferrer"><code>429 Too Many Requests</code></a> 才是语义正确的限流状态码，<code>503</code> 表示「服务不可用」会误导客户端与监控：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>limit_req_status 429;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="干跑模式" tabindex="-1">干跑模式 <a class="header-anchor" href="#干跑模式" aria-label="Permalink to &quot;干跑模式&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>limit_req_dry_run on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>只统计不拦截</strong>。上线新限流规则前先干跑一段时间，配合 <code>$limit_req_status</code> 变量观察会拦掉多少：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log_format limit &#39;$remote_addr &quot;$request&quot; limit=$limit_req_status&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>$limit_req_status</code> 取值：<code>PASSED</code>、<code>DELAYED</code>、<code>REJECTED</code>、<code>DELAYED_DRY_RUN</code>、<code>REJECTED_DRY_RUN</code>。</p><h2 id="limit-conn-并发连接数" tabindex="-1">limit_conn：并发连接数 <a class="header-anchor" href="#limit-conn-并发连接数" aria-label="Permalink to &quot;limit\\_conn：并发连接数&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>limit_conn_zone $binary_remote_addr zone=perip:10m;</span></span>
<span class="line"><span>limit_conn_zone $server_name        zone=perserver:10m;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    limit_conn perip     10;    # 每 IP 最多 10 个并发连接</span></span>
<span class="line"><span>    limit_conn perserver 1000;  # 本站总共最多 1000</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>与 <code>limit_req</code> 的区别：<strong>限的是「同时打开的连接数」而非「请求速率」</strong>。对下载站、流媒体更合适。</p><p><code>limit_conn_status</code> 同样建议改 <code>429</code>。</p><h2 id="limit-rate-带宽限速" tabindex="-1">limit_rate：带宽限速 <a class="header-anchor" href="#limit-rate-带宽限速" aria-label="Permalink to &quot;limit\\_rate：带宽限速&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /download/ {</span></span>
<span class="line"><span>    limit_rate      500k;      # 每连接 500 KB/s</span></span>
<span class="line"><span>    limit_rate_after 10m;      # 前 10 MB 不限速</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>limit_rate_after</code> 很实用：<strong>小文件全速，大文件才限速</strong>——既保证网页体验又防止大文件占满带宽。</p><p>注意限的是<strong>每个连接</strong>，一个客户端开 5 个连接就能拿到 5 倍带宽——要配合 <code>limit_conn</code> 使用。</p><p>可以用变量动态限速：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $http_user_agent $rate {</span></span>
<span class="line"><span>    default        1m;</span></span>
<span class="line"><span>    ~*bot          100k;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>limit_rate $rate;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="组合示例" tabindex="-1">组合示例 <a class="header-anchor" href="#组合示例" aria-label="Permalink to &quot;组合示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    limit_req_zone  $binary_remote_addr zone=api:10m rate=10r/s;</span></span>
<span class="line"><span>    limit_req_zone  $binary_remote_addr zone=login:10m rate=1r/m;</span></span>
<span class="line"><span>    limit_conn_zone $binary_remote_addr zone=conn:10m;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    limit_req_status  429;</span></span>
<span class="line"><span>    limit_conn_status 429;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    server {</span></span>
<span class="line"><span>        # 还原真实 IP（前面有 CDN 时必需）</span></span>
<span class="line"><span>        set_real_ip_from 10.0.0.0/8;</span></span>
<span class="line"><span>        real_ip_header   X-Forwarded-For;</span></span>
<span class="line"><span>        real_ip_recursive on;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        limit_conn conn 20;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        location /api/ {</span></span>
<span class="line"><span>            limit_req zone=api burst=20 nodelay;</span></span>
<span class="line"><span>            proxy_pass http://backend;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # 登录接口严格限流，防撞库</span></span>
<span class="line"><span>        location = /login {</span></span>
<span class="line"><span>            limit_req zone=login burst=3;</span></span>
<span class="line"><span>            proxy_pass http://backend;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        location /admin/ {</span></span>
<span class="line"><span>            allow 10.0.0.0/8;</span></span>
<span class="line"><span>            deny  all;</span></span>
<span class="line"><span>            auth_basic           &quot;Admin&quot;;</span></span>
<span class="line"><span>            auth_basic_user_file /etc/nginx/.htpasswd;</span></span>
<span class="line"><span>            proxy_pass http://backend;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        location /download/ {</span></span>
<span class="line"><span>            limit_rate       1m;</span></span>
<span class="line"><span>            limit_rate_after 10m;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/logging">日志</a>。</p>`,73)])])}const m=a(l,[["render",t]]);export{u as __pageData,m as default};
